const defaultRegionsCsv = 'Москва,Санкт-Петербург,Московская область';
const defaultOrgTypesCsv = 'школа,детский сад,лицей';

const regions = ($json.regionsCsv || defaultRegionsCsv).split(',').map(s => s.trim()).filter(Boolean);
const orgTypes = ($json.orgTypesCsv || defaultOrgTypesCsv).split(',').map(s => s.trim()).filter(Boolean);
const perQueryRaw = Number($json.searchResultsPerQuery || 10);
const perQuery = Math.max(1, Math.min(100, perQueryRaw));
const pagesRaw = Number($json.pagesPerQuery || 1);
const pagesPerQuery = Math.max(1, Math.min(10, pagesRaw));
const serperApiKey = $json.serperApiKey || '';
const gsheetId = $json.gsheetId || '';

if (!serperApiKey) {
  throw new Error('Set Seeds: заполните поле serperApiKey');
}
if (!gsheetId) {
  throw new Error('Set Seeds: заполните поле gsheetId');
}

const out = [];
for (const region of regions) {
  for (const orgType of orgTypes) {
    for (let page = 1; page <= pagesPerQuery; page += 1) {
      out.push({
        json: {
          region,
          orgType,
          perQuery,
          page,
          pagesPerQuery,
          serperApiKey,
          gsheetId,
          query: `официальный сайт ${orgType} ${region} директор телефон email`
        }
      });
    }
  }
}

return out;

const region = $item(0).$node['Split In Batches'].json.region;
const orgType = $item(0).$node['Split In Batches'].json.orgType;
const gsheetId = $item(0).$node['Split In Batches'].json.gsheetId || "";
const page = Number($item(0).$node['Split In Batches'].json.page || 1);
const organic = $json.organic || [];
return organic.map((r) => ({
  json: {
    region,
    orgType,
    page,
    sourceUrl: r.link || '',
    orgName: r.title || '',
    snippet: r.snippet || '',
    gsheetId
  }
}));

function firstMatch(text, regex) {
  const m = text.match(regex);
  return m ? m[0] : '';
}

const item = $item(0).$node['Parse Search Results'].json;
const html = typeof $json === 'string' ? $json : (JSON.stringify($json || {}));
const text = `${item.orgName}
${item.snippet}
${html}`;

const emailRegex = /[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/ig;
const phoneRegex = /(?:\+7|8)[\s(\-]*\d{3}[\s)\-]*\d{3}[\s\-]*\d{2}[\s\-]*\d{2}/g;
const fioRegex = /(?:директор|заведующ(?:ий|ая)|руководитель)[:\s]*([А-ЯЁ][а-яё]+\s+[А-ЯЁ][а-яё]+(?:\s+[А-ЯЁ][а-яё]+)?)/i;

const emails = Array.from(new Set((text.match(emailRegex) || []).map(e => e.toLowerCase())));
const phones = Array.from(new Set((text.match(phoneRegex) || []).map(p => p.replace(/\s+/g, ' ').trim())));

const mobile = phones.find(p => /\+7|8/.test(p)) || '';
const cityPhone = phones.find(p => p !== mobile) || '';

let leader = '';
const fioMatch = text.match(fioRegex);
if (fioMatch) leader = fioMatch[1].trim();

const now = new Date();
const currentYear = now.getFullYear().toString();
const freshSignals = [currentYear, (now.getFullYear() - 1).toString(), 'обновлено', 'актуаль', 'контакты'];
const freshnessScore = freshSignals.reduce((acc, s) => acc + (text.toLowerCase().includes(s.toLowerCase()) ? 1 : 0), 0);

return [{
  json: {
    region: item.region,
    organizationType: item.orgType,
    organizationName: item.orgName,
    leaderFullName: leader,
    mobilePhone: mobile,
    landlinePhone: cityPhone,
    email: emails[0] || '',
    sourceUrl: item.sourceUrl,
    gsheetId: item.gsheetId || "",
    freshnessScore,
    checkedAt: now.toISOString(),
    hasAnyContact: Boolean(leader || emails[0] || mobile || cityPhone)
  }
}];
